"build:viewer\": \"vite build --config vite.config.ts\",\n    \"build:package\": \"npm run build && npm run build:viewer\",\n    \"prepack\": \"npm run check:hermes-version && npm run build:package\",\n    \"sync:hermes-version\": \"node scripts/sync-hermes-version.cjs\",\n    \"check:hermes-version\": \"node scripts/sync-hermes-version.cjs --check\",\n    \"release:validate\": \"npm run lock:check && npm run verify:script-policy && npm run check:hermes-version && npm run lint && npm test\",\n    \"dev\": \"tsc -p tsconfig.json --watch\",\n    \"viewer:dev\": \"vite --config vite.config.ts\",\n    \"bridge\": \"tsx bridge.cts\",\n    \"bridge:daemon\": \"tsx bridge.cts --daemon\",\n    \"test\": \"vitest run\",\n    \"test:watch\": \"vitest\",\n    \"test:unit\": \"vitest run tests/unit\",\n    \"test:integration\": \"vitest run tests/integration\",\n    \"test:e2e\": \"vitest run tests/e2e\",\n    \"lint\": \"tsc -p tsconfig.json --noEmit\",\n    \"postinstall\": \"node scripts/postinstall.cjs\",\n    \"lock:normalize\": \"node scripts/normalize-sqlite-lock.cjs\",\n    \"lock:check\": \"node scripts/normalize-sqlite-lock.cjs --check\",\n    \"verify:native\": \"node scripts/verify-native-runtime.cjs\",\n    \"verify:script-policy\": \"node scripts/verify-script-policy.cjs\"\n  },\n  \"keywords\": [\n    \"memory\",\n    \"agent\",\n    \"reflect2evolve\",\n    \"self-evolution\",\n    \"skill-crystallization\",\n    \"openclaw\",\n    \"hermes\",\n    \"deepseek-harness\",\n    \"dsh-plugin\"\n  ],\n  \"license\": \"MIT\",\n  \"engines\": {\n    \"node\": \">=22.0.0\"\n  },\n  \"dependencies\": {\n    \"@huggingface/transformers\": \"4.2.0\",\n    \"@preact/signals\": \"^2.9.0\",\n    \"@sinclair/typebox\": \"^0.34.48\",\n    \"better-sqlite3\": \"13.0.3\",\n    \"preact\": \"^10.29.1\",\n    \"tsx\": \"^4.21.0\",\n    \"uuid\": \"^10.0.0\",\n    \"yaml\": \"^2.6.0\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-